using System.ClientModel;
using Azure.AI.OpenAI;
using OpenAI.Chat;

namespace MyApp.Evals.Tests;

/// <summary>
/// Returns a fixed response for stub-tier runs (no real LLM calls).
/// </summary>
internal sealed class StubChatClient : IChatClient
{
    public Task<ChatResponse> GetResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        CancellationToken cancellationToken = default)
    {
        var text = "This is a stub response for evaluation purposes. " +
                   "The agent would normally provide a detailed answer here based on the user's query. " +
                   "To see real responses, set EVAL_USE_REAL_AGENT=1 and wire a connection string.";
        var response = new ChatResponse(new ChatMessage(ChatRole.Assistant, text));
        return Task.FromResult(response);
    }

    public async IAsyncEnumerable<ChatResponseUpdate> GetStreamingResponseAsync(
        IEnumerable<ChatMessage> messages,
        ChatOptions? options = null,
        [System.Runtime.CompilerServices.EnumeratorCancellation] CancellationToken cancellationToken = default)
    {
        var response = await GetResponseAsync(messages, options, cancellationToken);
        yield return new ChatResponseUpdate(ChatRole.Assistant, response.Text);
    }

    public object? GetService(Type serviceType, object? serviceKey = null) => null;

    public void Dispose() { }
}

internal static class Wire
{
    public static IChatClient ResolveAgentClient() =>
        EvalEnv.UseRealAgent ? AgentChatClientFactory.Create() : new StubChatClient();

    public static IChatClient ResolveJudgeClient(IChatClient agentClient)
    {
        var judgeDeployment = Environment.GetEnvironmentVariable("EVAL_JUDGE_DEPLOYMENT_NAME");
        if (!string.IsNullOrEmpty(judgeDeployment))
        {
            // Override: use a different deployment for the judge.
            // Read config the same way as the agent factory.
            var builder = Host.CreateApplicationBuilder();
            builder.Configuration.AddUserSecrets(typeof(AgentChatClientFactory).Assembly, optional: true);

            var connStr = builder.Configuration.GetConnectionString("chat");
            if (string.IsNullOrEmpty(connStr))
                throw new InvalidOperationException(
                    "EVAL_JUDGE_DEPLOYMENT_NAME set but ConnectionStrings:chat is missing.");

            var parts = ParseConnStr(connStr);
            var endpoint = parts.GetValueOrDefault("Endpoint")
                ?? throw new InvalidOperationException("Connection string missing Endpoint.");

            AzureOpenAIClient aoaiClient;
            if (parts.TryGetValue("Key", out var key) && !string.IsNullOrEmpty(key))
                aoaiClient = new AzureOpenAIClient(new Uri(endpoint), new ApiKeyCredential(key));
            else
                aoaiClient = new AzureOpenAIClient(new Uri(endpoint), new Azure.Identity.DefaultAzureCredential());

            return aoaiClient.GetChatClient(judgeDeployment).AsIChatClient();
        }

        // Default: same client serves both agent and judge (cache benefits)
        return agentClient;
    }

    private static Dictionary<string, string> ParseConnStr(string connStr)
    {
        var result = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
        foreach (var part in connStr.Split(';', StringSplitOptions.RemoveEmptyEntries))
        {
            var idx = part.IndexOf('=');
            if (idx > 0)
                result[part[..idx].Trim()] = part[(idx + 1)..].Trim();
        }
        return result;
    }
}

